        "tier_all" to listOf("All types", "ሁሉም አይነቶች", "Gosa hundaa", "ኩሉ ዓይነት"),
        "tier_health_post" to listOf("Health Post", "የጤና ጣቢያ", "Buufata Fayyaa", "ጣብያ ጥዕና"),
        "tier_health_center" to listOf("Health Center", "የጤና ማዕከል", "Giddu-gala Fayyaa", "ማእከል ጥዕና"),
        "tier_primary" to listOf("Primary Hospital", "የመጀመሪያ ደረጃ ሆስፒታል", "Hospitaala Sadarkaa Jalqabaa", "ሆስፒታል ቀዳማይ ደረጃ"),
        "tier_general" to listOf("General Hospital", "ጠቅላላ ሆስፒታል", "Hospitaala Waliigalaa", "ሆስፒታል ሓፈሻዊ"),
        "tier_referral" to listOf("Referral & Specialized Hospital", "ሪፈራል እና ልዩ ሆስፒታል", "Hospitaala Rifeeraalii fi Addaa", "ሆስፒታል ሪፈራልን ፍሉይን"),
        "hs_title" to listOf("How the Ethiopian health system works", "የኢትዮጵያ የጤና ስርዓት እንዴት እንደሚሰራ", "Sirni fayyaa Itoophiyaa akkamitti akka hojjetu", "ስርዓት ጥዕና ኢትዮጵያ ብኸመይ ከም ዝሰርሕ"),
        "hs_tier1_title" to listOf("1. Health posts — your first stop", "1. የጤና ጣቢያዎች — የመጀመሪያ መድረሻዎ", "1. Buufata fayyaa — bakka jalqabaa kee", "1. ጣብያታት ጥዕና — ቀዳማይ መድረሻኻ"),
        "hs_tier1_body" to listOf("Health posts serve kebeles and are staffed by health extension workers. They give vaccinations, family planning, health education and basic care, and refer you to a health center when needed.", "የጤና ጣቢያዎች ቀበሌዎችን ያገለግላሉ እና በጤና ኤክስቴንሽን ሰራተኞች ይሰራሉ። ክትባቶችን፣ የቤተሰብ ምጣኔን፣ የጤና ትምህርት እና መሰረታዊ እንክብካቤ ይሰጣሉ፣ ሲያስፈልግም ወደ ጤና ማዕከል ይልክዎታል።", "Buufatni fayyaa ganda tajaajila, hojjettoota fayyaa babal'inaatiin hojjetama. Talaallii, karoora maatii, barnoota fayyaa fi kunuunsa bu'uuraa kenna, yoo barbaachise immoo gara giddu-gala fayyaatti si geessa.", "ጣብያታት ጥዕና ቀበሌታት የገልግሉ፣ ብሰራሕተኛታት ምዝርጋሕ ጥዕና እዮም ዝሰርሑ። ክታበት፣ ምውህሃድ ስድራቤት፣ ትምህርቲ ጥዕናን መሰረታዊ ክንክንን ይህቡ፣ ምስ ኣድልዮ ናብ ማእከል ጥዕና የለኽኹኻ።"),
        "hs_tier2_title" to listOf("2. Health centers", "2. የጤና ማዕከሎች", "2. Giddu-gala fayyaa", "2. ማእከላት ጥዕና"),
        "hs_tier2_body" to listOf("Health centers serve woredas with nurses, midwives and health officers. They offer outpatient care, delivery services, laboratory tests and referrals to hospitals.", "የጤና ማዕከሎች ወረዳዎችን በነርሶች፣ አዋላጆች እና የጤና መኮንኖች ያገለግላሉ። የውጭ ታካሚ እንክብካቤ፣ የወሊድ አገልግሎት፣ የላብራቶሪ ምርመራ እና ወደ ሆስፒታል ሪፈራል ይሰጣሉ።", "Giddu-galli fayyaa aanaa narsoota, deessistoota fi ogeessota fayyaatiin tajaajila. Yaala alaa, tajaajila da'umsaa, qorannoo laaboraatoorii fi rifeera gara hospitaalaa kenna.", "ማእከላት ጥዕና ወረዳታት ብነርሳት፣ ኣዋላጆምን ሞያውያን ጥዕናን የገልግሉ። ናይ ወጻኢ ሕሙም ክንክን፣ ኣገልግሎት ሕርሲ፣ ምርመራ ላብራቶሪን ናብ ሆስፒታል ሪፈራልን ይህቡ።"),
        "hs_tier3_title" to listOf("3. Hospitals", "3. ሆስፒታሎች", "3. Hospitaalota", "3. ሆስፒታላት"),
        "hs_tier3_body" to listOf("Primary hospitals serve zones, general hospitals serve regions, and referral & specialized hospitals (like Tikur Anbessa and St. Paul's) handle the most complex cases from across the country.", "የመጀመሪያ ደረጃ ሆስፒታሎች ዞኖችን፣ ጠቅላላ ሆስፒታሎች ክልሎችን ያገለግላሉ፣ ሪፈራል እና ልዩ ሆስፒታሎች (እንደ ጥቁር አንበሳ እና ቅዱስ ጳውሎስ) ደግሞ ከመላው ሀገር የሚመጡ በጣም ውስብስብ ጉዳዮችን ይቋቋማሉ።", "Hospitaalonni sadarkaa jalqabaa godina, hospitaalonni waliigalaa naannoo tajaajilu; hospitaalonni rifeeraalii fi addaa (akka Tikur Anbessaa fi Qulquulluu Phaawuloos) immoo dhimma cimaa biyya guutuu irraa dhufu too'atu.", "ሆስፒታላት ቀዳማይ ደረጃ ዞባታት፣ ሓፈሻዊ ሆስፒታላት ክልላት የገልግሉ፤ ሪፈራልን ፍሉይን ሆስፒታላት (ከም ጥቁር ኣንበሳን ቅዱስ ጳውሎስን) ድማ ካብ መላእ ሀገር ዝመጽእ ዝኸበደ ጉዳይ ይሕዙ።"),
        "hep_title" to listOf("Health Extension Program", "የጤና ኤክስቴንሽን ፕሮግራም", "Sagantaa Babal'ina Fayyaa", "መደብ ምዝርጋሕ ጥዕና"),
        "hep_body" to listOf("Health extension workers visit homes in every kebele to teach hygiene, vaccinate children, support mothers and link families to health posts. Ask your local health extension worker for help.", "የጤና ኤክስቴንሽን ሰራተኞች ንጽህናን ለማስተማር፣ ልጆችን ለመከተብ፣ እናቶችን ለመደገፍ እና ቤተሰቦችን ከጤና ጣቢያዎች ጋር ለማገናኘት በእያንዳንዱ ቀበሌ ቤት ለቤት ይጎበኛሉ። እርዳታ ለማግኘት የአካባቢዎን የጤና ኤክስቴንሽን ሰራተኛ ይጠይቁ።", "Hojjettoonni fayyaa babal'inaa qulqullina barsiisuuf, daa'imman talaaluuf, haadholi gargaaruuf fi maatii buufata fayyaatti walqabsiisuuf ganda hundaa keessatti mana mana dhaqu. Gargaarsa argachuuf hojjetaa fayyaa babal'inaa naannoo kee gaafadhu.", "ሰራሕተኛታት ምዝርጋሕ ጥዕና ንጽህና ንምምሃር፣ ህጻናት ንምኽታብ፣ ኣደታት ንምድጋፍን ስድራቤታት ምስ ጣብያ ጥዕና ንምትእስሳርን ኣብ ዝኾነ ቀበሌ ገዛ ገዛ ይበጽሑ። ሓገዝ ንምርካብ ናይ ከባቢኻ ሰራሕተኛ ምዝርጋሕ ጥዕና ሕተት።"),
        "cbhi_title" to listOf("Community-Based Health Insurance (CBHI)", "በማህበረሰብ ላይ የተመሰረተ የጤና መድን (CBHI)", "Inshuraansii Fayyaa Hawaasaa irratti Hundaa'e (CBHI)", "ኣብ ማሕበረሰብ ዝተመርኮሰ መድሕን ጥዕና (CBHI)"),
        "cbhi_what" to listOf("What is CBHI?", "CBHI ምንድን ነው?", "CBHI maali?", "CBHI እንታይ እዩ?"),
        "cbhi_what_body" to listOf("CBHI is a community health insurance scheme run through woredas. Member households pay a yearly contribution and get health services at public health centers and hospitals without paying at each visit.", "CBHI በወረዳዎች የሚተዳደር የማህበረሰብ የጤና መድን መርሃ ግብር ነው። አባል ቤተሰቦች ዓመታዊ መዋጮ ይከፍላሉ እና በእያንዳንዱ ጉብኝት ሳይከፍሉ በሕዝብ ጤና ማዕከሎች እና ሆስፒታሎች የጤና አገልግሎት ያገኛሉ።", "CBHI sagantaa inshuraansii fayyaa hawaasaa aanaa keessatti gaggeeffamu dha. Maanonni miseensa ta'an waggaatti kaffaltii kenna, tajaajila fayyaa giddu-gala fayyaa fi hospitaalota mootummaa irraa daawwannaa hunda irratti kaffaltii tokko malee argatu.", "CBHI ኣብ ወረዳታት ዝካየድ መደብ መድሕን ጥዕና ማሕበረሰብ እዩ። ኣባል ስድራቤታት ዓመታዊ ዕጽፍ ይኸፍሉ፣ ኣብ ህዝባዊ ማእከላት ጥዕናን ሆስፒታላትን ኣብ ነፍሲ ወከፍ ምብጻሕ ብዘይ ክፍሊት ኣገልግሎት ጥዕና ይረኽቡ።"),
        "cbhi_who" to listOf("Who can join?", "ማን መቀላቀል ይችላል?", "Eenyutu makachuu danda'a?", "መን ክጽንበር ይኽእል?"),
        "cbhi_who_body" to listOf("Households in the informal sector — farmers, daily workers, small traders and others without formal employment insurance — can join through their kebele and woreda.", "በመደበኛ ባልሆነ ዘርፍ ያሉ ቤተሰቦች — አርሶ አደሮች፣ የቀን ሰራተኞች፣ አነስተኛ ነጋዴዎች እና የመደበኛ ሥራ መድን የሌላቸው ሌሎች — በቀበሌያቸው እና በወረዳቸው መቀላቀል ይችላሉ።", "Maanonni seektara idilee keessa jiran — qonnaan bultoota, hojjettoota guyyaa, daldaltoota xixiqqoo fi kanneen inshuraansii hojii idilee hin qabne — ganda fi aanaa isaanitiin makachuu danda'u.", "ስድራቤታት ኣብ ዘይመደበኛ ዘርፊ — ሓረስቶት፣ ናይ መዓልቲ ሰራሕተኛታት፣ ንኡሳን ነጋዶን ካልኦት ዘይመደበኛ ስራሕ መድሕን ዘይብሎም — ብቀበሌኦምን ወረዳኦምን ክጽንበሩ ይኽእሉ።"),
        "cbhi_covers" to listOf("What does it cover?", "ምን ይሸፍናል?", "Maal uwwisa?", "እንታይ ይሽፍን?"),
        "cbhi_covers_body" to listOf("CBHI generally covers outpatient visits, admissions, medicines on the essential list, laboratory tests and delivery care at public facilities. Some services and referral hospitals may have rules — ask at your woreda health office.", "CBHI በአጠቃላይ የውጭ ታካሚ ጉብኝቶችን፣ ሆስፒታል መግባትን፣ በአስፈላጊ ዝርዝር ውስጥ ያሉ መድኃኒቶችን፣ የላብራቶሪ ምርመራዎችን እና በሕዝብ ተቋማት የወሊድ እንክብካቤን ይሸፍናል። አንዳንድ አገልግሎቶች እና ሪፈራል ሆስፒታሎች ደንቦች ሊኖራቸው ይችላል — በወረዳ ጤና ጽሕፈት ቤት ይጠይቁ።", "CBHI waliigala daawwannaa alaa, galmee hospitaalaa, qoricha tarree barbaachisoo keessa jiru, qorannoo laaboraatoorii fi kunuunsa da'umsaa dhaabbilee mootummaa keessatti uwwisa. Tajaajila tokko tokkoo fi hospitaalonni rifeeraalii seera qabaachuu danda'u — waajjira fayyaa aanaa kee gaafadhu.", "CBHI ብሓፈሻዊ ምብጻሕ ወጻኢ ሕሙማን፣ ምእታው ሆስፒታል፣ ኣብ ኣገዳሲ ዝርዝር ዘሎ መድሃኒት፣ ምርመራ ላብራቶሪን ክንክን ሕርሲ ኣብ ህዝባዊ ተቋማትን ይሽፍን። ገለ ኣገልግሎታትን ሪፈራል ሆስፒታላትን ደንቢ ክህልዎም ይኽእል እዩ — ኣብ ጽሕፈት ቤት ጥዕና ወረዳኻ ሕተት።"),
        "cbhi_how" to listOf("How to enrol", "እንዴት መመዝገብ ይቻላል", "Akkamitti galmaa'uun danda'ama", "ብኸመይ ምምዝጋብ ይከኣል"),
        "cbhi_how_body" to listOf("Visit your kebele administration or woreda health office with your household information. They will register your household and explain the contribution and the services covered.", "የቤተሰብ መረጃዎን ይዘው የቀበሌ አስተዳደርዎን ወይም የወረዳ ጤና ጽሕፈት ቤትን ይጎብኙ። ቤተሰብዎን ይመዘግባሉ እና መዋጮውን እና የሚሸፈኑትን አገልግሎቶች ያብራሩልዎታል።", "Odeeffannoo maatii kee fudhattee bulchiinsa ganda kee ykn waajjira fayyaa aanaa kee daawwadhu. Maatii kee galmeessanii kaffaltii fi tajaajila uwwifamu siif ibsu.", "ሓበሬታ ስድራቤትካ ሒዝካ ናብ ምምሕዳር ቀበሌኻ ወይ ናብ ጽሕፈት ቤት ጥዕና ወረዳኻ ኪድ። ስድራቤትካ ክመዝግብዎን ዕጽፍን ዝሽፈን ኣገልግሎትን ክነግሩኻ እዮም።"),
        "cbhi_cost" to listOf("How much does it cost?", "ምን ያህል ያስከፍላል?", "Hangam kaffaltii?", "ክንደይ ይኸፍል?"),
        "cbhi_cost_body" to listOf("The yearly contribution varies by region and household. There is no fixed national price in this app — ask at your woreda health office for the current amount.", "ዓመታዊ መዋጮው በክልል እና በቤተሰብ ይለያያል። በዚህ መተግበሪያ ውስጥ ቋሚ ብሔራዊ ዋጋ የለም — ወቅታዊውን መጠን በወረዳ ጤና ጽሕፈት ቤት ይጠይቁ።", "Kaffaltiin waggaa naannoo fi maatii irratti jijjiirama. Gatii biyyoolessaa dhaabbataa app kana keessa hin jiru — hamma ammaa waajjira fayyaa aanaa kee gaafadhu.", "ዓመታዊ ዕጽፍ ብክልልን ስድራቤትን ይፈላለ። ኣብዚ መተግበሪ ቋሚ ሃገራዊ ዋጋ የለን — ሕጂ ዘሎ መጠን ኣብ ጽሕፈት ቤት ጥዕና ወረዳኻ ሕተት።"),
        "blood_title" to listOf("Blood Bank & Donation", "የደም ባንክ እና ልገሳ", "Baankii Dhiigaa fi Kennaa", "ባንኪ ደምን ልገሳን"),
        "blood_who" to listOf("Who can donate?", "ማን መለገስ ይችላል?", "Eenyutu kennuu danda'a?", "መን ክልግስ ይኽእል?"),
        "blood_who_body" to listOf("Healthy adults aged 18–65 who weigh at least 50 kg can usually donate. You cannot donate if you are ill, pregnant, or have had certain illnesses recently — the blood bank will check you first.", "ዕድሜያቸው ከ18–65 የሆኑ ጤናማ አዋቂዎች ቢያንስ 50 ኪ.ግ የሚመዝኑ አብዛኛውን ጊዜ መለገስ ይችላሉ። የታመሙ፣ እርጉዝ ወይም በቅርብ ጊዜ የተወሰኑ ሕመሞች ካለብዎ መለገስ አይችሉም — የደም ባንኩ መጀመሪያ ይመረምርዎታል።", "Namoonni fayya qaban umuriin 18–65 kan ta'an, ulfaatina isaanii kg 50 ol ta'e, yeroo baay'ee kennuu danda'u. Yoo dhukkubsatte, ulfoofte ykn dhukkuba murtaa'e yeroo dhiyoo qabaatte kennuu hin dandeessu — baankiin dhiigaa jalqaba si sakatta'a.", "ጥዑያት ዓበይቲ ዕድመ 18–65 ዝኾኑ፣ ክብደት ብውሑዱ 50 ኪ.ግ ዝኾኑ፣ መብዛሕትኡ ግዜ ክልግሱ ይኽእሉ። ሕሙም እንተኾንካ፣ ጥንሲ እንተኾንካ፣ ወይ ኣብ ቀረባ ጊዜ ገለ ሕማማት እንተነበረካ ክትልግስ ኣይትኽእልን — ባንኪ ደም ቀዳማይ ክምርምረካ እዩ።"),
        "blood_where" to listOf("Where to donate", "የት መለገስ ይቻላል", "Eessatti kennuun danda'ama", "ኣበይ ምልጋስ ይከኣል"),
        "blood_where_body" to listOf("The National Blood Bank Service collects blood at Tikur Anbessa Hospital blood bank in Addis Ababa and at regional blood banks. Ask your nearest hospital for the current donation days.", "ብሔራዊ የደም ባንክ አገልግሎት ደም የሚሰበስበው በአዲስ አበባ በጥቁር አንበሳ ሆስፒታል የደም ባንክ እና በክልል የደም ባንኮች ነው። ወቅታዊ የልገሳ ቀናትን በአቅራቢያዎ ሆስፒታል ይጠይቁ።", "Tajaajilli Baankii Dhiigaa Biyyoolessaa dhiiga Finfinnee keessatti baankii dhiigaa Hospitaala Tikur Anbessaa fi baankota dhiigaa naannoo irraa walitti qaba. Guyyaa kennaa ammaa hospitaala dhihoo kee gaafadhu.", "ሃገራዊ ኣገልግሎት ባንኪ ደም ደም ኣብ ኣዲስ ኣበባ ኣብ ባንኪ ደም ሆስፒታል ጥቁር ኣንበሳን ኣብ ክልላዊ ባንክታት ደምን ይእክብ። ሕጂ ዘሎ መዓልታት ልገሳ ኣብ ዝቐረበ ሆስፒታል ሕተት።"),
        "blood_note" to listOf("Blood donation saves lives. One donation can help several patients. This is demo information — verify donation days with the hospital before you go.", "የደም ልገሳ ሕይወት ያድናል። አንድ ልገሳ ብዙ ታካሚዎችን ሊረዳ ይችላል። ይህ የማሳያ መረጃ ነው — ከመሄድዎ በፊት የልገሳ ቀናትን ከሆስፒታል ጋር ያረጋግጡ።", "Kennaan dhiigaa lubbuu baraara. Kennaa tokko dhukkubsattoota hedduu gargaaruu danda'a. Kun odeeffannoo fakkeenyaa dha — guyyaa kennaa dura hospitaalatti mirkaneessi.", "ልገሳ ደም ሂወት የድሕን እዩ። ሓንቲ ልገሳ ብዙሓት ሕሙማን ክትሕግዝ ትኽእል። እዚ ናይ ኣብነት ሓበሬታ እዩ — ቅድሚ ምኻድካ መዓልታት ልገሳ ምስ ሆስፒታል ኣረጋግጽ።"),
